CREATE TABLE iview_shift (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,shift_name VARCHAR(100) NOT NULL,start_minute INTEGER NOT NULL,end_minute INTEGER NOT NULL,weekdays VARCHAR(64) NOT NULL,zone_id VARCHAR(64) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,rule_version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE iview_planned_downtime (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,device_id BIGINT,start_at TIMESTAMP WITH TIME ZONE NOT NULL,end_at TIMESTAMP WITH TIME ZONE NOT NULL,reason VARCHAR(500) NOT NULL,rule_version BIGINT NOT NULL DEFAULT 1);
CREATE INDEX idx_iview_downtime_window ON iview_planned_downtime(device_id,start_at,end_at);
